    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20600385411' 
    AND (s.distrito LIKE '%PUEBLO LIBRE%' OR s.direccion LIKE '%PUEBLO LIBRE%')
    LIMIT 1
);

