SET @id_sede_221 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20548396850' 
    AND (s.distrito LIKE '%LA MOLINA%' OR s.direccion LIKE '%LA MOLINA%')
    LIMIT 1
);

SET @id_sede_221 = COALESCE(@id_sede_221, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '20548396850' LIMIT 1));

