    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20605669591' 
    AND (s.distrito LIKE '%LOS OLIVOS%' OR s.direccion LIKE '%LOS OLIVOS%')
    LIMIT 1
);

SET @id_sede_256 = COALESCE(@id_sede_256, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '20605669591' LIMIT 1));

