-- Hoja: BIOPACIFIC

SET @id_sede_358 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20600005163' 
    AND (s.distrito LIKE '%MIRAFLORES%' OR s.direccion LIKE '%MIRAFLORES%')
