-- Hoja: CA-vet el Gran Danes 

SET @id_sede_371 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20603630689' 
    AND (s.distrito LIKE '%CARABAYLLO%' OR s.direccion LIKE '%CARABAYLLO%')
    LIMIT 1
);

SET @id_sede_371 = COALESCE(@id_sede_371, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '20603630689' LIMIT 1));

