-- Hoja: CO-vet el Gran Danes

SET @id_sede_372 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20603630689' 
    AND (s.distrito LIKE '%COMAS%' OR s.direccion LIKE '%COMAS%')
    LIMIT 1
);

SET @id_sede_372 = COALESCE(@id_sede_372, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '20603630689' LIMIT 1));

