SET @id_sede_411 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '10079452209' 
    AND (s.distrito LIKE '%CARABAYLLO%' OR s.direccion LIKE '%CARABAYLLO%')
    LIMIT 1
);

SET @id_sede_411 = COALESCE(@id_sede_411, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '10079452209' LIMIT 1));

