-- Hoja: PET MAX SAC magdalena

SET @id_sede_413 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20610289321' 
    AND (s.distrito LIKE '%MAGDALENA%' OR s.direccion LIKE '%MAGDALENA%')
    LIMIT 1
);

SET @id_sede_413 = COALESCE(@id_sede_413, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '20610289321' LIMIT 1));

