    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20523846648' 
    AND (s.distrito LIKE '%LA MOLINA%' OR s.direccion LIKE '%LA MOLINA%')
    LIMIT 1
);

