SET @id_sede_431 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20523846648' 
    AND (s.distrito LIKE '%SAN BORJA%' OR s.direccion LIKE '%SAN BORJA%')
    LIMIT 1
);

SET @id_sede_431 = COALESCE(@id_sede_431, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '20523846648' LIMIT 1));

