SET @id_sede_449 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20602159826' 
    AND (s.distrito LIKE '%SAN MIGUEL%' OR s.direccion LIKE '%SAN MIGUEL%')
    LIMIT 1
);

