SET @id_sede_524 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20536780506' 
    AND (s.distrito LIKE '%CHORRILLOS%' OR s.direccion LIKE '%CHORRILLOS%')
    LIMIT 1
);

SET @id_sede_524 = COALESCE(@id_sede_524, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '20536780506' LIMIT 1));

