    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20605942742' 
    AND (s.distrito LIKE '%COMAS%' OR s.direccion LIKE '%COMAS%')
    LIMIT 1
);

