SET @id_sede_580 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '10103490249' 
    AND (s.distrito LIKE '%ATE%' OR s.direccion LIKE '%ATE%')
    LIMIT 1
);

SET @id_sede_580 = COALESCE(@id_sede_580, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '10103490249' LIMIT 1));

