SET @id_sede_691 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '10403501072' 
    AND (s.distrito LIKE '%LOS OLIVOS%' OR s.direccion LIKE '%LOS OLIVOS%')
    LIMIT 1
);

