SET @id_sede_701 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20545766842' 
    AND (s.distrito LIKE '%MAGDALENA%' OR s.direccion LIKE '%MAGDALENA%')
    LIMIT 1
);

SET @id_sede_701 = COALESCE(@id_sede_701, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '20545766842' LIMIT 1));

