-- Hoja: VET SANTA LUCIA SAC
SET @id_sede_952 = (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '20601751136' LIMIT 1);

-- Hoja: RENACER, SALUD Y BELLEZA S.A.C

SET @id_sede_953 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20609118343' 
    AND (s.distrito LIKE '%LINCE%' OR s.direccion LIKE '%LINCE%')
    LIMIT 1
);

SET @id_sede_953 = COALESCE(@id_sede_953, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '20609118343' LIMIT 1));

