-- Hoja: SJL-MASKOTOPIA 

SET @id_sede_1085 = (
    SELECT s.id_sede FROM Sede s 
    JOIN Empresa e ON s.id_empresa = e.id_empresa 
    WHERE e.ruc = '20608420933' 
    AND (s.distrito LIKE '%LURIGANCHO%' OR s.direccion LIKE '%LURIGANCHO%')
    LIMIT 1
);

SET @id_sede_1085 = COALESCE(@id_sede_1085, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '20608420933' LIMIT 1));

