    AND (s.distrito LIKE '%JESUS MARIA%' OR s.direccion LIKE '%JESUS MARIA%')
    LIMIT 1
);

SET @id_sede_1471 = COALESCE(@id_sede_1471, (SELECT s.id_sede FROM Sede s JOIN Empresa e ON s.id_empresa = e.id_empresa WHERE e.ruc = '20428674201' LIMIT 1));

